-- Opt-in simulated portfolio data. Password hash is bound separately by DemoSeeder.
SELECT md5('fitplix-demo-'||n)::uuid,case n when 1 then 'admin@fitplix.local' when 2 then 'demo@fitplix.local' else 'demo'||n||'@fitplix.local' end,
case n when 1 then 'Demo Product Manager' when 2 then 'Alex Morgan' else 'Demo Member '||n end,'PENDING',case when n=1 then 'ADMIN' else 'USER' end,
(current_date-(case when n=1 then 89 else 90-n*3 end))::timestamp at time zone 'UTC'+interval '6 hours',true FROM generate_series(1,30) n ON CONFLICT DO NOTHING;
UPDATE visitor v SET first_seen=u.created_at-interval '1 hour' FROM app_user u WHERE v.user_id=u.id AND v.demo;
SELECT md5('fitplix-demo-'||n)::uuid,23+n%15,'MALE',170+n%12,74+n%8,78+n%8,70+n%8,'MODERATE','LOSE','ANY',2500,2200,130,262,70,30,'UTC' FROM generate_series(1,27)n ON CONFLICT DO NOTHING;
CREATE TEMP TABLE demo_days AS SELECT md5('fitplix-demo-'||n)::uuid user_id,n,(current_date-d) date,d FROM generate_series(1,25)n CROSS JOIN generate_series(0,89)d JOIN app_user u ON u.id=md5('fitplix-demo-'||n)::uuid WHERE (current_date-d)>=(u.created_at at time zone 'UTC')::date AND (n<=3 OR (n+d)%case when n<=15 then 8 else 3 end<>0) AND NOT(n>20 AND d<14);
SELECT md5(m.id::text||f.id)::uuid,m.id,f.id,f.name,portion.g,f.calories*portion.g/100,f.protein*portion.g/100,f.carbs*portion.g/100,f.fat*portion.g/100,coalesce(f.fiber,0)*portion.g/100,coalesce(f.sugar,0)*portion.g/100,coalesce(f.sodium,0)*portion.g/100,f.fiber is null or f.sugar is null or f.sodium is null
FROM meal m JOIN app_user u ON u.id=m.user_id CROSS JOIN LATERAL (SELECT unnest(case m.meal_type when 'BREAKFAST' then ARRAY[173944,171265,168138] when 'LUNCH' then ARRAY[168878,171477] else ARRAY[172421,168878,171477] end) fid) selection JOIN food f ON f.id=selection.fid CROSS JOIN LATERAL (SELECT (case f.id when 173944 then 120 when 171265 then 250 when 168138 then 90 when 168878 then 200 when 171477 then 140 else 220 end)*(0.85+((extract(day from m.date)::int+ascii(substr(m.user_id::text,1,1)))%5)*.08) g)portion WHERE u.demo ON CONFLICT DO NOTHING;
UPDATE user_profile p SET weight=w.kg FROM (SELECT DISTINCT ON (user_id) user_id,kg FROM weight_entry ORDER BY user_id,date DESC)w JOIN app_user u ON u.id=w.user_id WHERE p.user_id=w.user_id AND u.demo;
DROP TABLE demo_days;
