INSERT INTO app_user(id,email,name,password_hash,role,created_at,demo)
INSERT INTO visitor(id,first_seen,user_id,demo) SELECT md5('fitplix-visitor-'||n)::uuid,(current_date-(90-(n%30+1)*3))::timestamp at time zone 'UTC'+interval '5 hours',case when n<=30 then md5('fitplix-demo-'||n)::uuid else null end,true FROM generate_series(1,60) n ON CONFLICT DO NOTHING;
INSERT INTO user_profile(user_id,age,sex,height,weight,start_weight,target_weight,activity,goal,diet,water_target,calorie_target,protein_target,carbs_target,fat_target,fiber_target,timezone)
INSERT INTO analytics_event(id,user_id,event_name,occurred_at,metadata) SELECT md5(u.id::text||'-registered')::uuid,u.id,'USER_REGISTERED',u.created_at,'{"simulated":true}' FROM app_user u WHERE demo ON CONFLICT DO NOTHING;
INSERT INTO analytics_event(id,user_id,event_name,occurred_at,metadata) SELECT md5(u.id::text||'-'||event)::uuid,u.id,event,u.created_at+case event when 'ONBOARDING_COMPLETED' then interval '5 minutes' else interval '6 minutes' end,'{"simulated":true}' FROM app_user u JOIN user_profile p ON p.user_id=u.id CROSS JOIN (VALUES('ONBOARDING_COMPLETED'),('CALORIE_GOAL_GENERATED')) e(event) WHERE u.demo ON CONFLICT DO NOTHING;
INSERT INTO experiment_assignment(id,user_id,experiment_id,variant,assigned_at) SELECT md5(u.id::text||'-experiment')::uuid,u.id,'onboarding-insight-v1',case when ascii(substr(u.id::text,1,1))%2=0 then 'A' else 'B' end,u.created_at+interval '6 minutes' FROM app_user u JOIN user_profile p ON p.user_id=u.id WHERE demo ON CONFLICT DO NOTHING;
INSERT INTO daily_target(id,user_id,date,calories,protein,carbs,fat,fiber,water) SELECT md5(user_id::text||date||'-target')::uuid,user_id,date,2200,130,262,70,30,2500 FROM demo_days ON CONFLICT DO NOTHING;
INSERT INTO meal(id,user_id,date,meal_type,created_at) SELECT md5(user_id::text||date||slot)::uuid,user_id,date,slot,date::timestamp at time zone 'UTC'+case slot when 'BREAKFAST' then interval '8 hours' when 'LUNCH' then interval '13 hours' else interval '18 hours' end FROM demo_days CROSS JOIN (VALUES('BREAKFAST'),('LUNCH'),('DINNER'))slots(slot) ON CONFLICT DO NOTHING;
INSERT INTO meal_item(id,meal_id,food_id,name,grams,calories,protein,carbs,fat,fiber,sugar,sodium,incomplete)
INSERT INTO water_entry(id,user_id,date,ml) SELECT md5(user_id::text||date||'-water')::uuid,user_id,date,1500+(n+d)%7*250 FROM demo_days ON CONFLICT DO NOTHING;
INSERT INTO activity_entry(id,user_id,date,steps,minutes) SELECT md5(user_id::text||date||'-activity')::uuid,user_id,date,3500+(n+d)%10*800,15+(n+d)%5*10 FROM demo_days ON CONFLICT DO NOTHING;
INSERT INTO weight_entry(id,user_id,date,kg) SELECT md5(dd.user_id::text||dd.date||'-weight')::uuid,dd.user_id,dd.date,p.start_weight-((dd.date-(u.created_at at time zone 'UTC')::date)*.045)+((dd.n+dd.d)%3)*.15 FROM demo_days dd JOIN user_profile p ON p.user_id=dd.user_id JOIN app_user u ON u.id=dd.user_id WHERE dd.d%7=0 OR dd.d=0 ON CONFLICT DO NOTHING;
INSERT INTO analytics_event(id,user_id,event_name,occurred_at,metadata) SELECT md5(m.id::text||'-event')::uuid,m.user_id,'MEAL_LOGGED',m.created_at,'{"simulated":true}' FROM meal m JOIN app_user u ON u.id=m.user_id WHERE u.demo ON CONFLICT DO NOTHING;
INSERT INTO analytics_event(id,user_id,event_name,occurred_at,metadata) SELECT md5(user_id::text||date||event)::uuid,user_id,event,date::timestamp at time zone 'UTC'+interval '20 hours','{"simulated":true}' FROM demo_days CROSS JOIN (VALUES('USER_LOGIN'),('WATER_LOGGED'),('ACTIVITY_LOGGED'))e(event) ON CONFLICT DO NOTHING;
INSERT INTO analytics_event(id,user_id,event_name,occurred_at,metadata) SELECT md5(user_id::text||date||'-weight-event')::uuid,user_id,'WEIGHT_UPDATED',date::timestamp at time zone 'UTC'+interval '20 hours','{"simulated":true}' FROM weight_entry w JOIN app_user u ON u.id=w.user_id WHERE u.demo ON CONFLICT DO NOTHING;
INSERT INTO analytics_event(id,user_id,event_name,occurred_at,metadata) SELECT md5(user_id::text||date||'-analytics')::uuid,user_id,'ANALYTICS_VIEWED',date::timestamp at time zone 'UTC'+interval '20 hours','{"simulated":true}' FROM demo_days WHERE (n+d)%3=0 ON CONFLICT DO NOTHING;
INSERT INTO saved_meal(id,user_id,name,meal_type,items,planned_date,created_at) SELECT md5(user_id::text||'-plan')::uuid,user_id,'Rice & lentil bowl','LUNCH','[{"foodId":168878,"grams":180},{"foodId":172421,"grams":220}]',current_date,u.created_at+interval '2 days' FROM user_profile p JOIN app_user u ON u.id=p.user_id WHERE u.demo AND extract(day from u.created_at)::int%2=0 ON CONFLICT DO NOTHING;
INSERT INTO analytics_event(id,user_id,event_name,occurred_at,metadata) SELECT md5(s.id::text||'-event')::uuid,s.user_id,'MEAL_PLAN_CREATED',s.created_at,'{"simulated":true}' FROM saved_meal s JOIN app_user u ON u.id=s.user_id WHERE u.demo ON CONFLICT DO NOTHING;
